function combatForm(edit){const ids=new Set(state.combat?.order.map(o=>o.actor)||[]),participants=scene().tokens.map(t=>state.actors.find(a=>a.id===t.actor)).filter(Boolean);const fields=participants.flatMap(a=>[field('include_'+a.id,a.name+' участвует',edit?ids.has(a.id):true,'checkbox'),field('side_'+a.id,'Сторона · '+a.name,a.side,'select',{options:SIDES})]);form(edit?'Изменить стороны':'В бой',fields,v=>{const ps=participants.filter(a=>v['include_'+a.id]).map(a=>({actor:a.id,side:v['side_'+a.id]}));return dispatch(edit?'combatSide':'combatStart',{participants:ps})},{submit:edit?'Обновить стороны':'Назначить и бросить инициативу',description:edit?'Смена стороны не перебрасывает инициативу. Включение новых участников пока доступно через ручные команды, очередь меняется отдельно.':'Сначала назначь стороны, затем подтвердись. Скрытые участники видны только ГМ. При ничьей можно вручную изменить очередь.'})}
function features(){information('Возможности текущей версии',`<p>Рабочая версия для проверки функций. Ниже указаны границы автоматизации.</p><table><tr><th>Раздел</th><th>Состояние</th></tr>${[
['Стол','Сцены, токены, масштаб, камера, сетка, пинг, линейка, изображения и области.'],['Персонажи','Ручной лист, навыки, владения, HP, КД, ресурсы, ячейки, портреты и владельцы.'],['Инвентарь','Создание, шаблоны, экипировка, стопки, контейнеры, подбор, передача и зелья.'],['Бой','Назначение сторон, инициатива, очередь, бюджет действий, атаки, урон, сопротивления и концентрация.'],['Проверки','Кости, формулы, навыки, спасброски, преимущество, эффекты и журнал расчётов.'],['Развитие','Ручное повышение уровня с предпросмотром; короткий и долгий отдых.'],['Совместная игра','Node.js + SQLite, ключи, роли, HTTP-опрос, приватные данные, восстановление и запускатель Tunnel.'],['Карта','Ручное раскрытие отдельных фрагментов; закрытые изображения не отправляются игрокам.'],['Перенос','JSON-архив с вложенными изображениями; локальная IndexedDB и серверная SQLite.']].map(([a,b])=>`<tr><td class="status-ok">${a}</td><td>${b}</td></tr>`).join('')}</table><h3>Пока вручную / ещё не реализовано</h3><p class="status-partial">Полный каталог SRD, помощник создания классов и всех уровней, мультикласс, автоматические реакции и дополнительные атаки, все условия, дистанция подбора и укрытие, стены и динамический свет, сложные отношения нескольких фракций, движение по заданному пути и трудная местность, сложение/подавление одинаковых эффектов, полноценный мобильный редактор, ZIP-архивы и Service Worker.</p><p>Оружие использует одну атаку за действие. Зелье лечения использует бонусное действие. Произвольная способность использует заданную формулу, ячейку и при необходимости спасбросок; её точное соответствие конкретному заклинанию подтверждает ГМ.</p><p>Базовые механики адаптированы из SRD 5.2.1. This work includes material from the System Reference Document 5.2.1 (“SRD 5.2.1”) by Wizards of the Coast LLC, available at https://www.dndbeyond.com/srd. The SRD 5.2.1 is licensed under the Creative Commons Attribution 4.0 International License, available at https://creativecommons.org/licenses/by/4.0/legalcode.</p>`)}
