function fit(){const sc=scene(),r=$('#viewport').getBoundingClientRect();camera.zoom=Math.min((r.width-60)/sc.width,(r.height-60)/sc.height,2);camera.x=(r.width-sc.width*camera.zoom)/2;camera.y=(r.height-sc.height*camera.zoom)/2;renderBoard();renderToolbar()}
function zoomAt(factor,e){const r=$('#viewport').getBoundingClientRect(),px=e?e.clientX-r.left:r.width/2,py=e?e.clientY-r.top:r.height/2,wx=(px-camera.x)/camera.zoom,wy=(py-camera.y)/camera.zoom;camera.zoom=Math.max(.12,Math.min(3,camera.zoom*factor));camera.x=px-wx*camera.zoom;camera.y=py-wy*camera.zoom;renderBoard();renderToolbar()}
