 if(object&&gm()&&e.altKey){const o=sc.objects.find(o=>o.id===object.dataset.object);form('Объект',[field('width','Ширина',o.width,'number'),field('height','Высота',o.height,'number'),field('rotation','Поворот',o.rotation,'number'),field('hidden','Скрыть',o.hidden,'checkbox'),field('remove','Удалить',false,'checkbox')],v=>dispatch('objectEdit',{...v,id:o.id}));return}
 const start={x:e.clientX,y:e.clientY,camera:{...camera},point:p},node=token||object;dragging=true;$('#viewport').setPointerCapture(e.pointerId);let moved=false;
 const move=ev=>{if(Math.hypot(ev.clientX-start.x,ev.clientY-start.y)>3)moved=true;if(tool==='measure'){const end=worldPoint(ev),dx=Math.abs(end.x-p.x)/sc.grid,dy=Math.abs(end.y-p.y)/sc.grid,ft=(sc.diagonal==='euclidean'?Math.hypot(dx,dy):Math.max(dx,dy))*sc.feet;$('#measure').textContent=ft.toFixed(1)+' футов';transientLine?.remove();transientLine=document.createElement('div');transientLine.className='measure-line';transientLine.style.cssText=`left:${p.x}px;top:${p.y}px;width:${Math.hypot(end.x-p.x,end.y-p.y)}px;transform:rotate(${Math.atan2(end.y-p.y,end.x-p.x)}rad)`;$('#world').append(transientLine)}else if(node&&(token||gm())){const end=worldPoint(ev);node.style.left=end.x+'px';node.style.top=end.y+'px'}else{camera.x=start.camera.x+ev.clientX-start.x;camera.y=start.camera.y+ev.clientY-start.y;$('#world').style.transform=`translate(${camera.x}px,${camera.y}px) scale(${camera.zoom})`}};
