 const cancel=()=>{dragging=false;$('#viewport').removeEventListener('pointermove',move);$('#viewport').removeEventListener('pointerup',up);$('#viewport').removeEventListener('pointercancel',cancel);renderBoard()};$('#viewport').addEventListener('pointermove',move);$('#viewport').addEventListener('pointerup',up);$('#viewport').addEventListener('pointercancel',cancel);
