function roomFields(create){return [field('registry','Адрес реестра Worker',globalThis.DUNGEON_TABLE_CONFIG?.registry||''),field('origin','Адрес сервера (если без реестра)',location.protocol==='http:'?location.origin:'http://127.0.0.1:8787'),field('room','Имя комнаты (латиница)','dnd-evening','text',{required:true}),field('password','Пароль комнаты','','password',{required:true}),field('name','Твоё имя',create?'Мастер':'Игрок','text',{required:true}),...(create?[field('admin','Ключ хозяина (data/admin-key.txt)','','password',{required:true}),field('useLocal','Загрузить в комнату текущую локальную кампанию',true,'checkbox')]:[])]}
async function connect(v,create){let origin=v.origin.trim().replace(/\/$/,'');const registry=v.registry.trim().replace(/\/$/,'');if(registry){if(!/^https:\/\/[a-z0-9.-]+\.workers\.dev$/.test(registry))throw new Error('Нужен HTTPS-адрес workers.dev.');const r=await fetch(registry+'/host',{cache:'no-store',signal:AbortSignal.timeout(10000)}).then(r=>r.json());if(!r.origin)throw new Error('Сервер не зарегистрирован. Запусти host.py.');origin=r.origin}if(!/^https:\/\/[a-z0-9.-]+(?::\d+)?$/.test(origin)&&!/^http:\/\/(127\.0\.0\.1|localhost):\d+$/.test(origin))throw new Error('Укажи HTTPS-адрес сервера или локальный http://127.0.0.1:порт.');if(location.protocol==='https:'&&origin.startsWith('http:'))throw new Error('Для GitHub Pages используй HTTPS-адрес туннеля.');const response=await fetch(origin+(create?'/api/lobby':'/api/lobby/join'),{method:'POST',headers:{'Content-Type':'application/json',...(create?{Authorization:'Bearer '+v.admin}:{})},body:JSON.stringify({room:v.room,password:v.password,name:v.name,...(create&&v.useLocal?{campaign:full}: {})}),signal:AbortSignal.timeout(30000)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Ошибка входа.');network={origin,registry,id:data.id,key:data.key,roomName:data.roomName,user:data.user};user=data.user;localStorage.setItem('dt-session',JSON.stringify(network));assetCache.clear();failedAssets.clear();digest='';section='table';await refresh(false);pollTimer=setTimeout(()=>refresh(),700);toast('Комната подключена. Назначь владельцев персонажей в разделе «Участники».')}
actions.createRoom=()=>{$('#dialog').close();form('Создать комнату',roomFields(true),v=>connect(v,true),{submit:'Создать',description:'Создание доступно по ключу хозяина сервера. Ключ регистрации Cloudflare сюда не подходит.'})};actions.joinRoom=()=>{$('#dialog').close();form('Войти игроком',roomFields(false),v=>connect(v,false),{submit:'Войти'})};actions.resumeRoom=async()=>{const n=JSON.parse(localStorage.getItem('dt-session'));if(!n)throw new Error('Нет сохранённого входа.');network=n;user=n.user;digest='';await rediscover();await refresh(false);pollTimer=setTimeout(()=>refresh(),700);$('#dialog').close()};actions.disconnect=async()=>{network=null;clearTimeout(pollTimer);user={id:'local-gm',name:'Мастер',role:'gm'};assetCache.clear();section='table';full=await localRead()||createCampaign();applyView();$('#dialog').close();$('#connection').textContent='Локально · сохранено'};actions.localRole=()=>{if(network)return;if(gm()){user={id:'local-player',name:'Локальный игрок',role:'player'};if(!full.actors.some(a=>a.owner===user.id))full.actors[0].owner=user.id}else user={id:'local-gm',name:'Мастер',role:'gm'};section='table';assetCache.clear();applyView();$('#dialog').close();$('#connection').textContent='Локально · '+(gm()?'ГМ':'вид игрока')};actions.restoreAccess=()=>{$('#dialog').close();form('Восстановленный доступ',[field('json','Данные доступа от ГМ','','textarea',{full:true})],async v=>{const n=JSON.parse(v.json);if(!n.id||!n.key||!n.origin)throw new Error('Неверные данные.');network=n;user=n.user;digest='';await refresh(false);localStorage.setItem('dt-session',JSON.stringify(network));pollTimer=setTimeout(()=>refresh(),700)})};actions.retryCommand=async()=>{if(!network||!lastCommand)return;try{await api(`/api/lobby/${network.id}/command`,{method:'POST',body:lastCommand})}catch(e){if(e.confirmed)lastCommand=null;throw e}lastCommand=null;digest='';await refresh(false);$('#dialog').close();toast('Запрос подтверждён.')};
$('#save-menu').onclick=()=>information('Кампании и резервные копии',`<p>JSON-архив включает изображения. Полный экспорт доступен ГМ. Импорт заменяет открытый проект после подтверждения.</p><div class="row wrap">${btn(gm()?'Экспорт кампании':'Экспорт доступных листов','export')}${gm()?btn('Импорт кампании','import')+btn('Новая кампания','newCampaign'):''}</div>`);
